#!/usr/bin/env python3
"""
SOLVER_SLR.py — Symbolic Logic Rule solver for SLR-Bench train-direction tasks.

Infer a Prolog rule of the form eastbound(T) :- Body. from labelled
(background_facts, direction_label) pairs using a property-based candidate
generation strategy followed by Prolog-verification via the local judge.
"""

import re
import itertools
import sys
from collections import defaultdict
from typing import Any, Dict, List, Tuple, Optional

sys.path.insert(0, "/workspace")
from rewards.slr_bench import reward, rule_complexity, _get_judge


# ---------------------------------------------------------------------------
# Fact parsing
# ---------------------------------------------------------------------------

_FACT_RE = re.compile(r"(\w+)\(([^)]*)\)")


def parse_facts(facts_str: str) -> List[Tuple[str, Tuple[str, ...]]]:
    """Parse a space-separated Prolog ground-atom string into a list of
    (predicate, (arg1, arg2, ...)) tuples."""
    return [
        (m.group(1), tuple(a.strip() for a in m.group(2).split(",")))
        for m in _FACT_RE.finditer(facts_str)
    ]


def extract_cars(facts: list) -> List[str]:
    """Return the list of car constants mentioned in the facts."""
    cars = set()
    for pred, args in facts:
        if pred == "has_car":
            cars.add(args[1])
    return list(cars)


# ---------------------------------------------------------------------------
# Property extraction helpers
# ---------------------------------------------------------------------------

# Predicates whose *second* argument is a categorical "value" that can appear
# in a rule body.  First argument is always a car constant or variable.
_VALUE_PREDICATES = {
    "car_color",
    "car_len",
    "has_wall",
    "has_roof",
    "has_payload",
    "car_type",
    "has_window",
}

# Predicates whose second argument is an integer.
_INT_PREDICATES = {
    "car_num",
    "has_wheel",
    "load_num",
    "passenger_num",
}


def extract_car_properties(facts: List[Tuple[str, Tuple[str, ...]]],
                           car: str) -> Dict[str, set]:
    """Return a dict pred_name -> set of values for a given car."""
    props: Dict[str, set] = defaultdict(set)
    for pred, args in facts:
        if args[0] == car and pred != "has_car":
            props[pred].add(args[1])
    return dict(props)


def collect_all_values(facts_per_train: List[List[Tuple[str, Tuple[str, ...]]]],
                       label: str) -> Dict[str, set]:
    """For a group of trains with the same label, collect all predicate ->
    value pairs across all cars in all trains."""
    all_vals: Dict[str, set] = defaultdict(set)
    for facts in facts_per_train:
        for pred, args in facts:
            if pred != "has_car" and len(args) == 2:
                all_vals[pred].add(args[1])
    return dict(all_vals)


# ---------------------------------------------------------------------------
# Candidate generation (in-Python filtering)
# ---------------------------------------------------------------------------

def train_has_property(facts: List[Tuple[str, Tuple[str, ...]]],
                       car_vars: List[str],
                       pred: str, value: str) -> bool:
    """Check whether at least one car in the train has predicate == value."""
    for car in car_vars:
        for p, args in facts:
            if p == pred and args[0] == car and args[1] == value:
                return True
    return False


def find_separating_single_props(
    positive_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    positive_cars: List[List[str]],
    negative_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    negative_cars: List[List[str]],
) -> List[Tuple[str, str]]:
    """Return all (predicate, value) pairs that are true for ALL positive
    examples and false for ALL negative examples."""
    candidates: Dict[str, set] = defaultdict(set)
    for facts in positive_facts:
        for pred, args in facts:
            if pred != "has_car" and len(args) == 2:
                candidates[pred].add(args[1])

    separating: List[Tuple[str, str]] = []
    for pred in candidates:
        for value in candidates[pred]:
            pos_ok = all(
                train_has_property(facts, cars, pred, value)
                for facts, cars in zip(positive_facts, positive_cars)
            )
            neg_ok = all(
                not train_has_property(facts, cars, pred, value)
                for facts, cars in zip(negative_facts, negative_cars)
            )
            if pos_ok and neg_ok:
                separating.append((pred, value))
    return separating


def find_separating_conjunctions(
    positive_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    positive_cars: List[List[str]],
    negative_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    negative_cars: List[List[str]],
    min_size: int = 2,
    max_size: int = 4,
) -> List[List[Tuple[str, str]]]:
    """Enumerate conjunctions of (pred, value) pairs of the given size that
    separate all positives from all negatives.

    For each positive train, at least one car must satisfy ALL literals in the
    conjunction.  No negative train may have any car that satisfies ALL literals.
    """
    # Gather candidate (pred, value) from positive examples
    candidates: Dict[str, set] = defaultdict(set)
    for facts in positive_facts:
        for pred, args in facts:
            if pred != "has_car" and len(args) == 2:
                candidates[pred].add(args[1])

    all_pairs = [(p, v) for p in candidates for v in candidates[p]]

    results: List[List[Tuple[str, str]]] = []
    for size in range(min_size, max_size + 1):
        for combo in itertools.combinations(all_pairs, size):
            if _conjunction_holds(combo, positive_facts, positive_cars) and \
               not _conjunction_negative(combo, negative_facts, negative_cars):
                results.append(list(combo))

    return results


def _conjunction_holds(
    combo: Tuple[Tuple[str, str], ...],
    facts_list: List[List[Tuple[str, Tuple[str, ...]]]],
    cars_list: List[List[str]],
) -> bool:
    """True if for every train, at least one car satisfies ALL literals."""
    for facts, cars in zip(facts_list, cars_list):
        found = False
        for car in cars:
            if all(
                any(p == pred and a[0] == car and a[1] == value
                    for p, a in facts)
                for pred, value in combo
            ):
                found = True
                break
        if not found:
            return False
    return True


def _conjunction_negative(
    combo: Tuple[Tuple[str, str], ...],
    facts_list: List[List[Tuple[str, Tuple[str, ...]]]],
    cars_list: List[List[str]],
) -> bool:
    """True if there EXISTS a negative train where a car satisfies ALL literals.
    We want this to be False (i.e., no negative train matches)."""
    for facts, cars in zip(facts_list, cars_list):
        for car in cars:
            if all(
                any(p == pred and a[0] == car and a[1] == value
                    for p, a in facts)
                for pred, value in combo
            ):
                return True
    return False


# ---------------------------------------------------------------------------
# Integer-range / arithmetic literals
# ---------------------------------------------------------------------------

def _int_literal_for_pred(pred: str) -> List[Tuple[str, int]]:
    """Return candidate integer literals for an integer predicate."""
    literals: List[Tuple[str, int]] = []
    if pred in _INT_PREDICATES:
        literals.append((f"{pred}(C, _N)", ">0"))  # _N > 0
        literals.append((f"{pred}(C, 0)", "==0"))
        for v in [1, 2, 3, 4, 5, 6]:
            literals.append((f"{pred}(C, {v})", f"=={v}"))
    return literals


def find_separating_int_rules(
    positive_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    positive_cars: List[List[str]],
    negative_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    negative_cars: List[List[str]],
) -> List[str]:
    """Find single integer-property rules that separate positive from negative."""
    results: List[str] = []

    # Gather all int values from positive examples
    int_vals: Dict[str, set] = defaultdict(set)
    for facts in positive_facts:
        for pred, args in facts:
            if pred in _INT_PREDICATES and len(args) == 2:
                try:
                    int_vals[pred].add(int(args[1]))
                except ValueError:
                    pass

    for pred, values in int_vals.items():
        # Test each specific integer value
        for v in sorted(values):
            rule = f"eastbound(T) :- has_car(T, C), {pred}(C, {v})."
            if _rule_matches_facts(rule, positive_facts, positive_cars) and \
               not _rule_matches_facts(rule, negative_facts, negative_cars):
                results.append(rule)

        # Test >0
        rule = f"eastbound(T) :- has_car(T, C), {pred}(C, N), N > 0."
        if _rule_matches_int_facts(">0", positive_facts, positive_cars, pred) and \
           not _rule_matches_int_facts(">0", negative_facts, negative_cars, pred):
            results.append(rule)

        # Test ==0
        rule = f"eastbound(T) :- has_car(T, C), {pred}(C, 0)."
        if _rule_matches_facts(rule, positive_facts, positive_cars) and \
           not _rule_matches_facts(rule, negative_facts, negative_cars):
            results.append(rule)

    return results


def _rule_matches_facts(
    rule: str, facts_list, cars_list,
) -> bool:
    """Check if a rule (as a string template) matches all examples."""
    # Parse the rule body into (predicate, value) literals
    body = rule.split(":-", 1)[1].rstrip(" .")
    body_clean = re.sub(r"\s+", " ", body)

    if "> 0" in body_clean or ">0" in body_clean:
        # Handle arithmetic
        parts = [s.strip() for s in body_clean.split(",")]
        pred_part = None
        for p in parts:
            if "(" in p and ")" in p and p.strip() != "has_car(T, C)" and not p.startswith("N"):
                pred_part = p
        if pred_part:
            pred_name = pred_part.split("(")[0]
            for facts, cars in zip(facts_list, cars_list):
                found = False
                for car in cars:
                    for p, args in facts:
                        if p == pred_name and len(args) == 2:
                            try:
                                if int(args[1]) > 0:
                                    found = True
                                    break
                            except ValueError:
                                pass
                if not found:
                    return False
        return True
    else:
        # Standard literal check
        parts = [s.strip() for s in body_clean.split(",")]
        car_preds = {}
        for p in parts:
            m = re.match(r"(\w+)\((\w+),\s*(.+)\)", p)
            if m:
                car_preds[m.group(2)] = (m.group(1), m.group(3).strip())

        for facts, cars in zip(facts_list, cars_list):
            found = False
            for car in cars:
                if car in car_preds:
                    pname, pval = car_preds[car]
                    if any(
                        p == pname and a[1] == pval
                        for p, a in facts
                    ):
                        found = True
                        break
            if not found:
                return False
        return True


def _rule_matches_int_facts(
    condition: str, facts_list, cars_list, pred: str,
) -> bool:
    """Check arithmetic-based rule matching."""
    for facts, cars in zip(facts_list, cars_list):
        found = False
        for car in cars:
            for p, args in facts:
                if p == pred and len(args) == 2:
                    try:
                        if condition == ">0" and int(args[1]) > 0:
                            found = True
                            break
                    except ValueError:
                        pass
        if not found:
            return False
    return True


# ---------------------------------------------------------------------------
# Verifier wrapper
# ---------------------------------------------------------------------------

def _evaluate_rule(rule: str, validation_program: str) -> float:
    """Evaluate a Prolog rule against validation program using the judge."""
    entry = {"validation program": validation_program}
    try:
        result = reward(rule, True, entry)
        return float(result.get("value", 0.0))
    except Exception:
        return 0.0


# ---------------------------------------------------------------------------
# Negation rules (\+ ... in Prolog)
# ---------------------------------------------------------------------------

def find_separating_negation_rules(
    positive_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    positive_cars: List[List[str]],
    negative_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    negative_cars: List[List[str]],
) -> List[str]:
    """Find rules using Prolog negation-as-failure.

    Pattern: eastbound(T) :- has_car(T, C), car_color(C, Colour), Colour \\= red.
    """
    results: List[str] = []

    # Collect all categorical values from positive examples
    all_values: Dict[str, set] = defaultdict(set)
    for facts in positive_facts:
        for pred, args in facts:
            if pred in _VALUE_PREDICATES and len(args) == 2:
                all_values[pred].add(args[1])

    for pred, values in all_values.items():
        # For each value, try "Colour \\= value" meaning: car has pred, but
        # pred value is NOT equal to 'value'.
        # This means: there must exist a car with pred, and its value is not 'value'
        for excluded in sorted(values):
            # Positive: every train must have at least one car with pred and value != excluded
            # Negative: every train must NOT have any car with pred and value != excluded
            #   (i.e., every car either doesn't have pred or has value == excluded)

            pos_ok = True
            for facts, cars in zip(positive_facts, positive_cars):
                found = False
                for car in cars:
                    for p, args in facts:
                        if p == pred and args[1] != excluded:
                            found = True
                            break
                    if found:
                        break
                if not found:
                    pos_ok = False
                    break

            if not pos_ok:
                continue

            neg_ok = True
            for facts, cars in zip(negative_facts, negative_cars):
                # Negative train should NOT match
                for car in cars:
                    for p, args in facts:
                        if p == pred and args[1] != excluded:
                            neg_ok = False
                            break
                    if not neg_ok:
                        break
                if not neg_ok:
                    break

            if pos_ok and neg_ok:
                results.append(
                    f"eastbound(T) :- has_car(T, C), {pred}(C, _X), _X \\\\= {excluded}."
                )

    return results


# ---------------------------------------------------------------------------
# Two-car rules (different car comparisons)
# ---------------------------------------------------------------------------

def find_separating_two_car_rules(
    positive_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    positive_cars: List[List[str]],
    negative_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    negative_cars: List[List[str]],
) -> List[str]:
    """Find rules involving two different cars in the same train."""
    results: [] = []  # type: ignore[var-annotated]
    return results


# ---------------------------------------------------------------------------
# Main solver
# ---------------------------------------------------------------------------

def solve_slr(examples: List[Tuple[str, str]],
              top_k: int = 5) -> Dict[str, Any]:
    """
    Main solver entry point.

    Parameters
    ----------
    examples : list of (facts_string, direction_label)
               facts_string  — space-separated Prolog ground facts for one train
               direction_label — "eastbound" or "westbound"
    top_k     : number of top candidate rules to return

    Returns
    -------
    dict with at least:
        "success"  : bool
        "program"  : best Prolog rule string
        "top_k_programs" : list of top-K rule strings
        "score"    : float 0–1
    """

    # ---- Separate positive and negative examples ----
    positive: List[Tuple[str, str]] = [(f, l) for f, l in examples if l == "eastbound"]
    negative: List[Tuple[str, str]] = [(f, l) for f, l in examples if l == "westbound"]

    if not positive or not negative:
        return {
            "success": False,
            "program": "",
            "top_k_programs": [],
            "score": 0.0,
        }

    # ---- Parse facts and extract cars ----
    pos_facts: List[List[Tuple[str, Tuple[str, ...]]]] = [parse_facts(f) for f, _ in positive]
    pos_cars: List[List[str]] = [extract_cars(pf) for pf in pos_facts]
    neg_facts: List[List[Tuple[str, Tuple[str, ...]]]] = [parse_facts(f) for f, _ in negative]
    neg_cars: List[List[str]] = [extract_cars(nf) for nf in neg_facts]

    # ---- Collect validation program (use first positive + first negative) ----
    validation_program = ""
    if positive:
        validation_program += "\n".join(
            parse_facts_for_prolog(f) for f, _ in positive
        )
    if negative:
        validation_program += "\n".join(
            parse_facts_for_prolog(f) for f, _ in negative
        )

    all_candidates: List[Tuple[str, int]] = []  # (rule_string, complexity)

    # ---- Stage 1: Single-property rules ----
    separating = find_separating_single_props(
        pos_facts, pos_cars, neg_facts, neg_cars
    )
    for pred, value in separating:
        rule = f"eastbound(T) :- has_car(T, C), {pred}(C, {value})."
        complexity = rule_complexity(rule)
        all_candidates.append((rule, complexity))

    # ---- Stage 1b: Integer-property rules ----
    int_rules = find_separating_int_rules(
        pos_facts, pos_cars, neg_facts, neg_cars
    )
    for rule in int_rules:
        complexity = rule_complexity(rule)
        all_candidates.append((rule, complexity))

    # ---- Stage 1c: Negation rules ----
    neg_rules = find_separating_negation_rules(
        pos_facts, pos_cars, neg_facts, neg_cars
    )
    for rule in neg_rules:
        complexity = rule_complexity(rule)
        all_candidates.append((rule, complexity))

    # ---- Stage 2: Two-property conjunctions ----
    conj2 = find_separating_conjunctions(
        pos_facts, pos_cars, neg_facts, neg_cars,
        min_size=2, max_size=2,
    )
    for combo in conj2:
        body_parts = [f"has_car(T, C)"]
        for pred, value in combo:
            body_parts.append(f"{pred}(C, {value})")
        rule = "eastbound(T) :- " + ", ".join(body_parts) + "."
        complexity = rule_complexity(rule)
        all_candidates.append((rule, complexity))

    # ---- Stage 3: Three-property conjunctions ----
    conj3 = find_separating_conjunctions(
        pos_facts, pos_cars, neg_facts, neg_cars,
        min_size=3, max_size=3,
    )
    for combo in conj3:
        body_parts = [f"has_car(T, C)"]
        for pred, value in combo:
            body_parts.append(f"{pred}(C, {value})")
        rule = "eastbound(T) :- " + ", ".join(body_parts) + "."
        complexity = rule_complexity(rule)
        all_candidates.append((rule, complexity))

    # ---- Stage 4: Four-property conjunctions ----
    conj4 = find_separating_conjunctions(
        pos_facts, pos_cars, neg_facts, neg_cars,
        min_size=4, max_size=4,
    )
    for combo in conj4:
        body_parts = [f"has_car(T, C)"]
        for pred, value in combo:
            body_parts.append(f"{pred}(C, {value})")
        rule = "eastbound(T) :- " + ", ".join(body_parts) + "."
        complexity = rule_complexity(rule)
        all_candidates.append((rule, complexity))

    # ---- Stage 5: Five-property conjunctions (last resort) ----
    conj5 = find_separating_conjunctions(
        pos_facts, pos_cars, neg_facts, neg_cars,
        min_size=5, max_size=5,
    )
    for combo in conj5:
        body_parts = [f"has_car(T, C)"]
        for pred, value in combo:
            body_parts.append(f"{pred}(C, {value})")
        rule = "eastbound(T) :- " + ", ".join(body_parts) + "."
        complexity = rule_complexity(rule)
        all_candidates.append((rule, complexity))

    # ---- Deduplicate candidates ----
    seen: set = set()
    unique_candidates: List[Tuple[str, int]] = []
    for rule, comp in all_candidates:
        if rule not in seen:
            seen.add(rule)
            unique_candidates.append((rule, comp))

    # ---- Score candidates using verifier ----
    scored: List[Tuple[str, float, int]] = []
    for rule, complexity in unique_candidates:
        score = _evaluate_rule(rule, validation_program)
        scored.append((rule, score, complexity))

    # Sort by (score desc, complexity asc)
    scored.sort(key=lambda x: (-x[1], x[2]))

    # ---- Return results ----
    top_rules = scored[:top_k]
    top_programs = [r[0] for r in top_rules]
    best_score = top_rules[0][1] if top_rules else 0.0
    best_rule = top_rules[0][0] if top_rules else ""

    return {
        "success": best_score >= 1.0,
        "program": best_rule,
        "top_k_programs": top_programs,
        "score": best_score,
    }


def parse_facts_for_prolog(facts_str: str) -> str:
    """Convert a facts_string into multi-line Prolog facts with train IDs."""
    lines = []
    facts = parse_facts(facts_str)

    # Extract train ID from first has_car fact
    train_id = None
    cars = []
    for pred, args in facts:
        if pred == "has_car":
            train_id = args[0]
            cars.append(args[1])

    if not train_id:
        return ""

    # Add train ID fact
    lines.append(f"eastbound({train_id}).")

    # Add all car facts
    for pred, args in facts:
        if pred == "has_car":
            lines.append(f"{pred}({args[0]}, {args[1]}).")
        elif len(args) == 2 and args[0] in cars:
            lines.append(f"{pred}({args[0]}, {args[1]}).")
        elif pred not in ("has_car",):
            # Include other facts that may be relevant
            lines.append(f"{pred}({args[0]}, {args[1]}).")

    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

if __name__ == "__main__":
    import json
    with open("/workspace/DEMOS.json") as f:
        data = json.load(f)

    # Test with first few demos
    for i in range(min(5, len(data))):
        d = data[i]
        examples = list(zip(d["input_examples"], d["output_examples"]))
        result = solve_slr(examples)
        print(f"\n=== Demo {i} ({d['difficulty']}, {d['rule_complexity']}) ===")
        print(f"  Success: {result['success']}")
        print(f"  Score: {result['score']}")
        print(f"  Program: {result['program']}")
        if result['top_k_programs']:
            print(f"  Top-K: {result['top_k_programs'][:3]}")

