    "car_num",
    "has_wheel",
    "load_num",
    "passenger_num",
}


def extract_car_properties(facts: List[Tuple[str, Tuple[str, ...]]],
                           car: str) -> Dict[str, set]:
    """Return a dict pred_name -> set of values for a given car."""
    props: Dict[str, set] = defaultdict(set)
    for pred, args in facts:
        if args[0] == car and pred != "has_car":
            props[pred].add(args[1])
    return dict(props)


def collect_all_values(facts_per_train: List[List[Tuple[str, Tuple[str, ...]]]],
                       label: str) -> Dict[str, set]:
    """For a group of trains with the same label, collect all predicate ->
    value pairs across all cars in all trains."""
    all_vals: Dict[str, set] = defaultdict(set)
    for facts in facts_per_train:
        for pred, args in facts:
            if pred != "has_car" and len(args) == 2:
                all_vals[pred].add(args[1])
    return dict(all_vals)


# ---------------------------------------------------------------------------
# Candidate generation (in-Python filtering)
# ---------------------------------------------------------------------------

def train_has_property(facts: List[Tuple[str, Tuple[str, ...]]],
                       car_vars: List[str],
                       pred: str, value: str) -> bool:
    """Check whether at least one car in the train has predicate == value."""
    for car in car_vars:
        for p, args in facts:
            if p == pred and args[0] == car and args[1] == value:
                return True
    return False


def find_separating_single_props(
    positive_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    positive_cars: List[List[str]],
    negative_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    negative_cars: List[List[str]],
) -> List[Tuple[str, str]]:
    """Return all (predicate, value) pairs that are true for ALL positive
    examples and false for ALL negative examples."""
    candidates: Dict[str, set] = defaultdict(set)
    for facts in positive_facts:
        for pred, args in facts:
            if pred != "has_car" and len(args) == 2:
                candidates[pred].add(args[1])

    separating: List[Tuple[str, str]] = []
    for pred in candidates:
        for value in candidates[pred]:
            pos_ok = all(
                train_has_property(facts, cars, pred, value)
                for facts, cars in zip(positive_facts, positive_cars)
