def find_separating_conjunctions(
    positive_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    positive_cars: List[List[str]],
    negative_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    negative_cars: List[List[str]],
    min_size: int = 2,
    max_size: int = 4,
) -> List[List[Tuple[str, str]]]:
    """Enumerate conjunctions of (pred, value) pairs of the given size that
    separate all positives from all negatives.

    For each positive train, at least one car must satisfy ALL literals in the
    conjunction.  No negative train may have any car that satisfies ALL literals.
    """
    # Gather candidate (pred, value) from positive examples
    candidates: Dict[str, set] = defaultdict(set)
    for facts in positive_facts:
        for pred, args in facts:
            if pred != "has_car" and len(args) == 2:
                candidates[pred].add(args[1])

    all_pairs = [(p, v) for p in candidates for v in candidates[p]]

    results: List[List[Tuple[str, str]]] = []
