    cars_list: List[List[str]],
) -> bool:
    """True if for every train, at least one car satisfies ALL literals."""
    for facts, cars in zip(facts_list, cars_list):
        found = False
        for car in cars:
            if all(
                any(p == pred and a[0] == car and a[1] == value
                    for p, a in facts)
                for pred, value in combo
            ):
                found = True
                break
        if not found:
            return False
    return True


def _conjunction_negative(
    combo: Tuple[Tuple[str, str], ...],
    facts_list: List[List[Tuple[str, Tuple[str, ...]]]],
    cars_list: List[List[str]],
) -> bool:
    """True if there EXISTS a negative train where a car satisfies ALL literals.
    We want this to be False (i.e., no negative train matches)."""
    for facts, cars in zip(facts_list, cars_list):
        for car in cars:
            if all(
                any(p == pred and a[0] == car and a[1] == value
                    for p, a in facts)
                for pred, value in combo
            ):
                return True
    return False


