#!/usr/bin/env python3
"""
SOLVER.py — Symbolic Logic Rule solver for SLR-Bench train-direction tasks.

Infer a Prolog rule of the form eastbound(T) :- Body. from labelled
(background_facts, direction_label) pairs using a property-based candidate
generation strategy followed by Prolog-verification via the local judge.
"""

import re
import itertools
import sys
from collections import defaultdict
from typing import Any, Dict, List, Tuple, Optional

sys.path.insert(0, "/workspace")
from rewards.slr_bench import reward, rule_complexity


# ---------------------------------------------------------------------------
# Fact parsing
# ---------------------------------------------------------------------------

_FACT_RE = re.compile(r"(\w+)\(([^)]*)\)")


def parse_facts(facts_str: str) -> List[Tuple[str, Tuple[str, ...]]]:
    """Parse a space-separated Prolog ground-atom string into a list of
    (predicate, (arg1, arg2, ...)) tuples."""
    return [
        (m.group(1), tuple(a.strip() for a in m.group(2).split(",")))
        for m in _FACT_RE.finditer(facts_str)
    ]


def extract_cars(facts: List[Tuple[str, Tuple[str, ...]]]) -> List[str]:
    """Return the list of car constants mentioned in the facts."""
    cars = set()
    for pred, args in facts:
        if pred == "has_car":
            cars.add(args[1])
    return list(cars)


def extract_train_id(facts: List[Tuple[str, Tuple[str, ...]]]) -> Optional[str]:
    """Extract the train ID from facts."""
    for pred, args in facts:
        if pred == "has_car":
            return args[0]
    return None


# ---------------------------------------------------------------------------
# Domain predicate lists
# ---------------------------------------------------------------------------

# Predicates whose second argument is a categorical "value" that can appear
# in a rule body. First argument is always a car constant or variable.
_VALUE_PREDICATES = {
    "car_color",
    "car_len",
    "has_wall",
    "has_roof",
    "has_payload",
    "car_type",
    "has_window",
}

# Predicates whose second argument is an integer.
_INT_PREDICATES = {
    "car_num",
    "has_wheel",
    "load_num",
    "passenger_num",
}


def is_value_predicate(pred: str) -> bool:
    return pred in _VALUE_PREDICATES


def is_int_predicate(pred: str) -> bool:
    return pred in _INT_PREDICATES


# ---------------------------------------------------------------------------
# Property helpers
# ---------------------------------------------------------------------------

def train_has_literal(facts: List[Tuple[str, Tuple[str, ...]]],
                      car_vars: List[str],
                      pred: str, value: str) -> bool:
    """Check whether at least one car in the train has pred(Car, value)."""
    for car in car_vars:
        for p, args in facts:
            if p == pred and args[0] == car and args[1] == value:
                return True
    return False


def train_has_conjunction(
    facts: List[Tuple[str, Tuple[str, ...]]],
    car_vars: List[str],
    combo: List[Tuple[str, str]],
) -> bool:
    """Check whether at least one car in the train satisfies ALL literals
    in the conjunction."""
    for car in car_vars:
        if all(
            any(p == pred and a[0] == car and a[1] == value
                for p, a in facts)
            for pred, value in combo
        ):
            return True
    return False


def train_has_int_literal(facts: List[Tuple[str, Tuple[str, ...]]],
                          car_vars: List[str],
                          pred: str, condition: str) -> bool:
    """Check an integer predicate with arithmetic condition."""
    for car in car_vars:
        for p, args in facts:
            if p == pred and args[0] == car and len(args) == 2:
                try:
                    v = int(args[1])
                    if condition == ">0" and v > 0:
                        return True
                    elif condition == "==0" and v == 0:
                        return True
                except ValueError:
                    pass
    return False


# ---------------------------------------------------------------------------
# Candidate generators
# ---------------------------------------------------------------------------

def find_separating_single_props(
    pos_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    pos_cars: List[List[str]],
    neg_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    neg_cars: List[List[str]],
) -> List[Tuple[str, str]]:
    """Return all (predicate, value) pairs that are true for ALL positive
    examples and false for ALL negative examples."""
    candidates: set = set()
    for facts in pos_facts:
        for pred, args in facts:
            if pred != "has_car" and len(args) == 2:
                candidates.add((pred, args[1]))

    separating: List[Tuple[str, str]] = []
    for pred, value in candidates:
        pos_ok = all(
            train_has_literal(facts, cars, pred, value)
            for facts, cars in zip(pos_facts, pos_cars)
        )
        neg_ok = all(
            not train_has_literal(facts, cars, pred, value)
            for facts, cars in zip(neg_facts, neg_cars)
        )
        if pos_ok and neg_ok:
            separating.append((pred, value))
    return separating


def find_separating_int_rules(
    pos_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    pos_cars: List[List[str]],
    neg_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    neg_cars: List[List[str]],
) -> List[str]:
    """Find integer-property rules that separate positive from negative."""
    results: List[str] = []

    # Gather all int values from positive examples
    int_vals: Dict[str, set] = defaultdict(set)
    for facts in pos_facts:
        for pred, args in facts:
            if pred in _INT_PREDICATES and len(args) == 2:
                try:
                    int_vals[pred].add(int(args[1]))
                except ValueError:
                    pass

    for pred, values in int_vals.items():
        for v in sorted(values):
            rule = f"eastbound(T) :- has_car(T, C), {pred}(C, {v})."
            if train_has_conjunction_batch(
                pos_facts, pos_cars, [(pred, str(v))]
            ) and not train_has_conjunction_batch(
                neg_facts, neg_cars, [(pred, str(v))]
            ):
                results.append(rule)

        # Test >0
        rule = f"eastbound(T) :- has_car(T, C), {pred}(C, N), N > 0."
        pos_ok = all(
            train_has_int_literal(facts, cars, pred, ">0")
            for facts, cars in zip(pos_facts, pos_cars)
        )
        neg_ok = all(
            not train_has_int_literal(facts, cars, pred, ">0")
            for facts, cars in zip(neg_facts, neg_cars)
        )
        if pos_ok and neg_ok:
            results.append(rule)

        # Test ==0
        rule = f"eastbound(T) :- has_car(T, C), {pred}(C, 0)."
        if train_has_conjunction_batch(
            pos_facts, pos_cars, [(pred, "0")]
        ) and not train_has_conjunction_batch(
            neg_facts, neg_cars, [(pred, "0")]
        ):
            results.append(rule)

    return results


def find_separating_negation_rules(
    pos_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    pos_cars: List[List[str]],
    neg_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    neg_cars: List[List[str]],
) -> List[str]:
    """Find rules using Prolog negation-as-failure.
    Pattern: eastbound(T) :- has_car(T, C), pred(C, _X), _X \\= excluded.
    """
    results: List[str] = []

    all_values: Dict[str, set] = defaultdict(set)
    for facts in pos_facts:
        for pred, args in facts:
            if pred in _VALUE_PREDICATES and len(args) == 2:
                all_values[pred].add(args[1])

    for pred, values in all_values.items():
        for excluded in sorted(values):
            # Positive: every train must have at least one car with pred
            #            and value != excluded
            # Negative: no train may have any car with pred and value != excluded

            pos_ok = True
            for facts, cars in zip(pos_facts, pos_cars):
                found = False
                for car in cars:
                    for p, args in facts:
                        if p == pred and args[1] != excluded:
                            found = True
                            break
                    if found:
                        break
                if not found:
                    pos_ok = False
                    break

            if not pos_ok:
                continue

            neg_ok = True
            for facts, cars in zip(neg_facts, neg_cars):
                for car in cars:
                    for p, args in facts:
                        if p == pred and args[1] != excluded:
                            neg_ok = False
                            break
                    if not neg_ok:
                        break
                if not neg_ok:
                    break

            if pos_ok and neg_ok:
                results.append(
                    f"eastbound(T) :- has_car(T, C), {pred}(C, _X), _X \\\\= {excluded}."
                )

    return results


def find_separating_conjunctions(
    pos_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    pos_cars: List[List[str]],
    neg_facts: List[List[Tuple[str, Tuple[str, ...]]]],
    neg_cars: List[List[str]],
    min_size: int = 2,
    max_size: int = 4,
) -> List[List[Tuple[str, str]]]:
    """Enumerate conjunctions of (pred, value) pairs that separate all
    positives from all negatives."""
    candidates: Dict[str, set] = defaultdict(set)
    for facts in pos_facts:
        for pred, args in facts:
            if pred != "has_car" and len(args) == 2:
                candidates[pred].add(args[1])

    all_pairs = [(p, v) for p in candidates for v in candidates[p]]

    results: List[List[Tuple[str, str]]] = []
    for size in range(min_size, max_size + 1):
        for combo in itertools.combinations(all_pairs, size):
            combo_list = list(combo)
            if train_has_conjunction_batch(
                pos_facts, pos_cars, combo_list
            ) and not train_has_conjunction_batch(
                neg_facts, neg_cars, combo_list
            ):
                results.append(combo_list)

    return results


def train_has_conjunction_batch(
    facts_list: List[List[Tuple[str, Tuple[str, ...]]]],
    cars_list: List[List[str]],
    combo: List[Tuple[str, str]],
) -> bool:
    """Check that ALL trains have at least one car satisfying ALL literals."""
    for facts, cars in zip(facts_list, cars_list):
        if not train_has_conjunction(facts, cars, combo):
            return False
    return True


# ---------------------------------------------------------------------------
# Verifier wrapper
# ---------------------------------------------------------------------------

def _evaluate_rule(rule: str, validation_program: str) -> float:
    """Evaluate a Prolog rule against validation program using the judge."""
    entry = {"validation program": validation_program}
    try:
        result = reward(rule, True, entry)
        return float(result.get("value", 0.0))
    except Exception:
        return 0.0


def _validate_candidate(rule: str, validation_program: str) -> Tuple[bool, float]:
    """Test a candidate rule via the verifier. Returns (perfect, score)."""
    score = _evaluate_rule(rule, validation_program)
    return (score >= 1.0, score)


# ---------------------------------------------------------------------------
# Build validation program from examples
# ---------------------------------------------------------------------------

def build_validation_program(
    examples: List[Tuple[str, str]]
) -> str:
    """Build a complete Prolog knowledge base from the examples for
    verification purposes."""
    lines: List[str] = []
    seen_trains: set = set()

    for facts_str, label in examples:
        facts = parse_facts(facts_str)
        train_id = extract_train_id(facts)
        if not train_id or train_id in seen_trains:
            continue
        seen_trains.add(train_id)

        direction = label  # "eastbound" or "westbound"
        lines.append(f"{direction}({train_id}).")

        for pred, args in facts:
            if pred == "has_car":
                lines.append(f"{pred}({args[0]}, {args[1]}).")
            elif pred == train_id:
                pass  # already added above
            else:
                lines.append(f"{pred}({', '.join(args)}).")

    return "\n".join(lines) + "\n"


# ---------------------------------------------------------------------------
# Main solver
# ---------------------------------------------------------------------------

def solve_slr(examples: List[Tuple[str, str]],
              top_k: int = 5) -> Dict[str, Any]:
    """
    Main solver entry point.

    Parameters
    ----------
    examples : list of (facts_string, direction_label)
               facts_string  — space-separated Prolog ground facts for one train
               direction_label — "eastbound" or "westbound"
    top_k     : number of top candidate rules to return

    Returns
    -------
    dict with at least:
        "success"  : bool
        "program"  : best Prolog rule string
        "top_k_programs" : list of top-K rule strings
        "score"    : float 0–1
    """

    # ---- Separate positive and negative examples ----
    pos_pairs: List[Tuple[str, str]] = [(f, l) for f, l in examples if l == "eastbound"]
    neg_pairs: List[Tuple[str, str]] = [(f, l) for f, l in examples if l == "westbound"]

    if not pos_pairs or not neg_pairs:
        return {
            "success": False,
            "program": "",
            "top_k_programs": [],
            "score": 0.0,
        }

    # ---- Parse facts and extract cars ----
    pos_facts: List[List[Tuple[str, Tuple[str, ...]]]] = [parse_facts(f) for f, _ in pos_pairs]
    pos_cars: List[List[str]] = [extract_cars(pf) for pf in pos_facts]
    neg_facts: List[List[Tuple[str, Tuple[str, ...]]]] = [parse_facts(f) for f, _ in neg_pairs]
    neg_cars: List[List[str]] = [extract_cars(nf) for nf in neg_facts]

    # ---- Build validation program ----
    validation_program = build_validation_program(examples)

    # ---- Candidate generation and scoring ----
    all_candidates: List[Tuple[str, int]] = []  # (rule_string, complexity)

    # Stage 1: Single-property rules
    separating = find_separating_single_props(
        pos_facts, pos_cars, neg_facts, neg_cars
    )
    for pred, value in separating:
        rule = f"eastbound(T) :- has_car(T, C), {pred}(C, {value})."
        complexity = rule_complexity(rule)
        all_candidates.append((rule, complexity))

    # Stage 1b: Integer-property rules
    int_rules = find_separating_int_rules(
        pos_facts, pos_cars, neg_facts, neg_cars
    )
    for rule in int_rules:
        complexity = rule_complexity(rule)
        all_candidates.append((rule, complexity))

    # Stage 1c: Negation rules
    neg_rules = find_separating_negation_rules(
        pos_facts, pos_cars, neg_facts, neg_cars
    )
    for rule in neg_rules:
        complexity = rule_complexity(rule)
        all_candidates.append((rule, complexity))

    # Stage 2: Two-property conjunctions
    conj2 = find_separating_conjunctions(
        pos_facts, pos_cars, neg_facts, neg_cars,
        min_size=2, max_size=2,
    )
    for combo in conj2:
        body_parts = [f"has_car(T, C)"]
        for pred, value in combo:
            body_parts.append(f"{pred}(C, {value})")
        rule = "eastbound(T) :- " + ", ".join(body_parts) + "."
        complexity = rule_complexity(rule)
        all_candidates.append((rule, complexity))

    # Stage 3: Three-property conjunctions
