            combo_list = list(combo)
            if train_has_conjunction_batch(
                pos_facts, pos_cars, combo_list
            ) and not train_has_conjunction_batch(
                neg_facts, neg_cars, combo_list
            ):
                results.append(combo_list)

    return results


def train_has_conjunction_batch(
    facts_list: List[List[Tuple[str, Tuple[str, ...]]]],
    cars_list: List[List[str]],
    combo: List[Tuple[str, str]],
) -> bool:
    """Check that ALL trains have at least one car satisfying ALL literals."""
    for facts, cars in zip(facts_list, cars_list):
        if not train_has_conjunction(facts, cars, combo):
            return False
    return True


# ---------------------------------------------------------------------------
# Verifier wrapper
# ---------------------------------------------------------------------------

def _evaluate_rule(rule: str, validation_program: str) -> float:
    """Evaluate a Prolog rule against validation program using the judge."""
    entry = {"validation program": validation_program}
    try:
        result = reward(rule, True, entry)
        return float(result.get("value", 0.0))
    except Exception:
        return 0.0


def _validate_candidate(rule: str, validation_program: str) -> Tuple[bool, float]:
    """Test a candidate rule via the verifier. Returns (perfect, score)."""
    score = _evaluate_rule(rule, validation_program)
    return (score >= 1.0, score)


# ---------------------------------------------------------------------------
# Build validation program from examples
# ---------------------------------------------------------------------------

def build_validation_program(
    examples: List[Tuple[str, str]]
) -> str:
    """Build a complete Prolog knowledge base from the examples for
    verification purposes."""
    lines: List[str] = []
    seen_trains: set = set()

    for facts_str, label in examples:
        facts = parse_facts(facts_str)
        train_id = extract_train_id(facts)
        if not train_id or train_id in seen_trains:
            continue
        seen_trains.add(train_id)

        direction = label  # "eastbound" or "westbound"
        lines.append(f"{direction}({train_id}).")

        for pred, args in facts:
            if pred == "has_car":
                lines.append(f"{pred}({args[0]}, {args[1]}).")
            elif pred == train_id:
                pass  # already added above
            else:
                lines.append(f"{pred}({', '.join(args)}).")

