    return True


def _neg_none(
    facts_list, cars_list,
    pred: str, value: str,
) -> bool:
    """No example has any car with pred != value (i.e. all cars have == value)."""
    for facts, cars in zip(facts_list, cars_list):
        if _neg_any(facts, cars, pred, value):
            return False
    return True


# ------------------------------------------------------------------
# Universal-negation helpers (demo 77: no car has X)
# ------------------------------------------------------------------

def _universal_neg_any(
    facts, cars,
    pred: str, value: str,
) -> bool:
    """Does the train have AT LEAST ONE car with pred(Car, value)?
    Returns True if found (i.e. the negation fails)."""
    for car in cars:
