#!/usr/bin/env python3
"""
SOLVER.py — Symbolic Logic Rule solver for SLR-Bench train-direction tasks.

Infer a Prolog rule of the form eastbound(T) :- Body. from labelled
(background_facts, direction_label) pairs using a multi-stage property-based
candidate generation strategy.  Candidates are filtered purely in Python
to minimize the number of calls to the SWI-Prolog verifier.
"""

import re
import itertools
import sys
from collections import defaultdict
from typing import Any, Dict, List, Tuple, Optional

sys.path.insert(0, "/workspace")
from rewards.slr_bench import reward, rule_complexity


# ======================================================================
# 1. Fact parsing
# ======================================================================

_FACT_RE = re.compile(r"(\w+)\(([^)]*)\)")


def parse_facts(facts_str: str) -> List[Tuple[str, Tuple[str, ...]]]:
    """Parse a space-separated Prolog ground-atom string."""
    return [
        (m.group(1), tuple(a.strip() for a in m.group(2).split(",")))
        for m in _FACT_RE.finditer(facts_str)
    ]


def extract_train_id(facts: List[Tuple[str, Tuple[str, ...]]]) -> Optional[str]:
    for pred, args in facts:
        if pred == "has_car":
            return args[0]
    return None


def extract_cars(facts: List[Tuple[str, Tuple[str, ...]]]) -> List[str]:
    return [args[1] for pred, args in facts if pred == "has_car"]


# ======================================================================
# 2. Predicate classification
# ======================================================================

_VALUE_PREDICATES = {
    "car_color", "car_len", "has_wall", "has_roof",
    "has_payload", "car_type", "has_window",
}

_INT_PREDICATES = {
    "car_num", "has_wheel", "load_num", "passenger_num",
}


def is_value_pred(p: str) -> bool:
    return p in _VALUE_PREDICATES


def is_int_pred(p: str) -> bool:
    return p in _INT_PREDICATES


# ======================================================================
# 3. In-Python matching helpers
# ======================================================================

def _any_car(facts, cars, pred, value) -> bool:
    """Does any car satisfy pred(Car, value)?"""
    for car in cars:
        for p, a in facts:
            if p == pred and a[0] == car and a[1] == value:
                return True
    return False


def _all_match(
    facts_list, cars_list,
    pred: str, value: str,
) -> bool:
    """All examples have at least one car satisfying pred(Car, value)."""
    for facts, cars in zip(facts_list, cars_list):
        if not _any_car(facts, cars, pred, value):
            return False
    return True


def _none_match(
    facts_list, cars_list,
    pred: str, value: str,
) -> bool:
    """No example has any car satisfying pred(Car, value)."""
    for facts, cars in zip(facts_list, cars_list):
        if _any_car(facts, cars, pred, value):
            return False
    return True


def _any_conj(
    facts, cars,
    combo: List[Tuple[str, str]],
) -> bool:
    """Does any car satisfy ALL literals in the conjunction?"""
    for car in cars:
        if all(
            any(p == pred and a[0] == car and a[1] == value
                for p, a in facts)
            for pred, value in combo
        ):
            return True
    return False


def _all_conj(
    facts_list, cars_list,
    combo: List[Tuple[str, str]],
) -> bool:
    """All examples have at least one car satisfying ALL literals."""
    for facts, cars in zip(facts_list, cars_list):
        if not _any_conj(facts, cars, combo):
            return False
    return True


def _none_conj(
    facts_list, cars_list,
    combo: List[Tuple[str, str]],
) -> bool:
    """No example has any car satisfying ALL literals."""
    for facts, cars in zip(facts_list, cars_list):
        if _any_conj(facts, cars, combo):
            return False
    return True


# ------------------------------------------------------------------
# Integer predicate helpers
# ------------------------------------------------------------------

def _int_any(facts, cars, pred, condition: str) -> bool:
    """Does any car satisfy an integer predicate with the given condition?"""
    for car in cars:
        for p, a in facts:
            if p == pred and a[0] == car and len(a) == 2:
                try:
                    v = int(a[1])
                    if condition == ">0" and v > 0:
                        return True
                    elif condition == "==0" and v == 0:
                        return True
                except ValueError:
                    pass
    return False


def _int_all(facts_list, cars_list, pred, condition: str) -> bool:
    for facts, cars in zip(facts_list, cars_list):
        if not _int_any(facts, cars, pred, condition):
            return False
    return True


def _int_none(facts_list, cars_list, pred, condition: str) -> bool:
    for facts, cars in zip(facts_list, cars_list):
        if _int_any(facts, cars, pred, condition):
            return False
    return True


# ------------------------------------------------------------------
# Negation helpers (X \\= excluded)
# ------------------------------------------------------------------

def _neg_any(
    facts, cars,
    pred: str, value: str,
) -> bool:
    """Does any car have the predicate with a value different from `value`?"""
    for car in cars:
        for p, a in facts:
            if p == pred and a[0] == car and a[1] != value:
                return True
    return False


def _neg_all(
    facts_list, cars_list,
    pred: str, value: str,
) -> bool:
    """All examples have at least one car with pred value != excluded."""
    for facts, cars in zip(facts_list, cars_list):
        if not _neg_any(facts, cars, pred, value):
            return False
    return True


def _neg_none(
    facts_list, cars_list,
    pred: str, value: str,
) -> bool:
    """No example has any car with pred value != excluded (all == excluded)."""
    for facts, cars in zip(facts_list, cars_list):
        if _neg_any(facts, cars, pred, value):
            return False
    return True


# ------------------------------------------------------------------
# Universal-negation helpers (demo 77: \\+ ...)
# ------------------------------------------------------------------

def _universal_neg_any(
    facts, cars,
    pred: str, value: str,
) -> bool:
    """Does the train have AT LEAST ONE car with pred(Car, value)?"""
    for car in cars:
        for p, a in facts:
            if p == pred and a[0] == car and a[1] == value:
                return True
    return False


def _universal_neg_all(
    facts_list, cars_list,
    pred: str, value: str,
) -> bool:
    """No example has any car satisfying the predicate."""
    for facts, cars in zip(facts_list, cars_list):
        if _universal_neg_any(facts, cars, pred, value):
            return False
    return True


def _universal_neg_some(
    facts_list, cars_list,
    pred: str, value: str,
) -> bool:
    """At least one example has a car satisfying the predicate."""
    for facts, cars in zip(facts_list, cars_list):
        if _universal_neg_any(facts, cars, pred, value):
            return True
    return False


# ======================================================================
# 4. Candidate generation
# ======================================================================

def _gather_candidates(facts_list):
    """Gather all unique (pred, value) pairs from examples."""
    cands: set = set()
    for facts in facts_list:
        for p, a in facts:
            if p != "has_car" and len(a) == 2:
                cands.add((p, a[1]))
    return cands


def gen_single_props(
    pos_facts, pos_cars, neg_facts, neg_cars,
) -> List[Tuple[str, str]]:
    """Single-property separating rules: pred(Car, value)."""
    cands = _gather_candidates(pos_facts)
    out: List[Tuple[str, str]] = []
    for pred, value in cands:
        if _all_match(pos_facts, pos_cars, pred, value) and \
           _none_match(neg_facts, neg_cars, pred, value):
            out.append((pred, value))
    return out


def gen_int_props(
    pos_facts, pos_cars, neg_facts, neg_cars,
) -> List[Tuple[str, str]]:
    """Integer-property separating rules."""
    vals: Dict[str, set] = defaultdict(set)
    for facts in pos_facts:
        for p, a in facts:
            if is_int_pred(p) and len(a) == 2:
                try:
                    vals[p].add(int(a[1]))
                except ValueError:
                    pass

    out: List[Tuple[str, str]] = []
    for pred, values in vals.items():
        for v in sorted(values):
            if _all_match(pos_facts, pos_cars, pred, str(v)) and \
               _none_match(neg_facts, neg_cars, pred, str(v)):
                out.append((pred, str(v)))
        if _int_all(pos_facts, pos_cars, pred, ">0") and \
           _int_none(neg_facts, neg_cars, pred, ">0"):
            out.append((pred, ">0"))
        if _all_match(pos_facts, pos_cars, pred, "0") and \
           _none_match(neg_facts, neg_cars, pred, "0"):
            out.append((pred, "0"))
    return out


def gen_negation_rules(
    pos_facts, pos_cars, neg_facts, neg_cars,
) -> List[Tuple[str, str]]:
    """Rules of the form pred(Car, X), X \\= excluded.

    All positive examples have at least one car with pred != excluded,
    but ALL cars in all negative examples have pred == excluded.
    """
    vals: Dict[str, set] = defaultdict(set)
    for facts in pos_facts:
        for p, a in facts:
            if is_value_pred(p) and len(a) == 2:
                vals[p].add(a[1])

    out: List[Tuple[str, str]] = []
    for pred, values in vals.items():
        for excluded in sorted(values):
            if _neg_all(pos_facts, pos_cars, pred, excluded) and \
               _neg_none(neg_facts, neg_cars, pred, excluded):
                out.append((pred, excluded))
    return out


def gen_universal_negation(
    pos_facts, pos_cars, neg_facts, neg_cars,
) -> List[Tuple[str, str]]:
    """Rules of the form \\+ ( has_car(T, C), pred(C, val) ).

    No positive example has ANY car with pred(Car, val),
    but at least one negative example does.
    """
    vals: Dict[str, set] = defaultdict(set)
    for facts in pos_facts:
        for p, a in facts:
            if len(a) == 2:
                vals[p].add(a[1])

    out: List[Tuple[str, str]] = []
    for pred, values in vals.items():
        for val in sorted(values):
            if _universal_neg_all(pos_facts, pos_cars, pred, val) and \
               _universal_neg_some(neg_facts, neg_cars, pred, val):
                out.append((pred, val))
    return out


def gen_conjunctions(
    pos_facts, pos_cars, neg_facts, neg_cars,
    min_size: int = 2,
    max_size: int = 5,
) -> List[List[Tuple[str, str]]]:
    """Multi-property conjunctions separating positive from negative."""
    cands = _gather_candidates(pos_facts)
    all_pairs = list(cands)

    out: List[List[Tuple[str, str]]] = []
    for size in range(min_size, max_size + 1):
        for combo in itertools.combinations(all_pairs, size):
            if _all_conj(pos_facts, pos_cars, list(combo)) and \
               _none_conj(neg_facts, neg_cars, list(combo)):
                out.append(list(combo))
    return out


def gen_mixed_int_conjunctions(
    pos_facts, pos_cars, neg_facts, neg_cars,
) -> List[List[Tuple[str, str, str]]]:
    """Find conjunctions: (cat_pred, cat_val, int_pred, condition).
    e.g., car_type=passenger AND load_num > 0 on same car.
    """
    cat_vals: Dict[str, set] = defaultdict(set)
    for facts in pos_facts:
        for p, a in facts:
            if is_value_pred(p) and len(a) == 2:
                cat_vals[p].add(a[1])

    int_vals: Dict[str, set] = defaultdict(set)
    for facts in pos_facts:
        for p, a in facts:
            if is_int_pred(p) and len(a) == 2:
                try:
                    int_vals[p].add(int(a[1]))
                except ValueError:
                    pass

    out: List[List[Tuple[str, str, str]]] = []

    for cat_pred, cat_val_set in cat_vals.items():
        for cat_val in cat_val_set:
            for int_pred in int_vals:
                for condition in [">0"]:
                    # Check each train
                    pos_ok = True
                    neg_ok = True

                    for pf, pc in zip(pos_facts, pos_cars):
                        found = False
                        for car in pc:
                            # Check same car has both conditions
                            cat_match = any(
                                p == cat_pred and a[0] == car and a[1] == cat_val
                                for p, a in pf
                            )
                            int_match = False
                            if cat_match:
                                for p, a in pf:
                                    if p == int_pred and a[0] == car and len(a) == 2:
                                        try:
                                            if condition == ">0" and int(a[1]) > 0:
                                                int_match = True
                                        except ValueError:
                                            pass
                            if cat_match and int_match:
                                found = True
                                break
                        if not found:
                            pos_ok = False
                            break

                    if not pos_ok:
                        continue

                    for nf, nc in zip(neg_facts, neg_cars):
                        for car in nc:
                            cat_match = any(
                                p == cat_pred and a[0] == car and a[1] == cat_val
                                for p, a in nf
                            )
                            int_match = False
                            if cat_match:
                                for p, a in nf:
                                    if p == int_pred and a[0] == car and len(a) == 2:
                                        try:
                                            if condition == ">0" and int(a[1]) > 0:
                                                int_match = True
                                        except ValueError:
                                            pass
                            if cat_match and int_match:
                                neg_ok = False
                                break
                        if not neg_ok:
                            break

                    if pos_ok and neg_ok:
                        # Build rule string
                        body = f"has_car(T, C), {cat_pred}(C, {cat_val}), {int_pred}(C, N), N > 0."
                        rule = f"eastbound(T) :- {body}"
                        out.append((rule, rule_complexity(rule)))

    return out


# ======================================================================
# 5. Rule string construction
# ======================================================================

def rule_for_single(pred: str, value: str) -> str:
    """Build rule for a single categorical property."""
    return f"eastbound(T) :- has_car(T, C), {pred}(C, {value})."


def rule_for_int(pred: str, condition: str) -> str:
    """Build rule for an integer property with arithmetic condition."""
    return f"eastbound(T) :- has_car(T, C), {pred}(C, N), N > 0."


def rule_for_negation(pred: str, excluded: str) -> str:
    """Build rule using Prolog inequality."""
    return f"eastbound(T) :- has_car(T, C), {pred}(C, _X), _X \\\\= {excluded}."


def rule_for_universal_neg(pred: str, val: str) -> str:
    """Build rule using Prolog negation-as-failure."""
    return f"eastbound(T) :- \\+ ( has_car(T, C), {pred}(C, {val}) )."


def rule_for_conjunction(combo: List[Tuple[str, str]]) -> str:
    """Build rule for a conjunction of categorical properties."""
    parts = ["has_car(T, C)"] + [f"{p}(C, {v})" for p, v in combo]
    return "eastbound(T) :- " + ", ".join(parts) + "."


def rule_for_mixed(cat_pred: str, cat_val: str, int_pred: str) -> str:
    """Build rule for categorical + integer > 0 conjunction on same car."""
    return (
        f"eastbound(T) :- has_car(T, C), "
        f"{cat_pred}(C, {cat_val}), "
        f"{int_pred}(C, N), N > 0."
    )


# ======================================================================
# 6. Verifier wrapper (minimize calls!)
# ======================================================================

def _evaluate_rule(rule: str, validation_program: str) -> float:
    """Score a single rule via the SWI-Prolog verifier."""
    try:
        entry = {"validation program": validation_program}
        result = reward(rule, True, entry)
        return float(result.get("value", 0.0))
    except Exception:
        return 0.0


# ======================================================================
# 7. Build validation program from examples
# ======================================================================

def build_validation_program(examples: List[Tuple[str, str]]) -> str:
    """Build complete Prolog KB from examples for verification."""
    lines: List[str] = []
    seen: set = set()
    for facts_str, label in examples:
        facts = parse_facts(facts_str)
        tid = extract_train_id(facts)
        if not tid or tid in seen:
            continue
        seen.add(tid)
        lines.append(f"{label}({tid}).")
        for pred, args in facts:
            if pred == "has_car":
                lines.append(f"{pred}({args[0]}, {args[1]}).")
            else:
                lines.append(f"{pred}({', '.join(args)}).")
    return "\n".join(lines) + "\n"


# ======================================================================
# 8. Main solver
# ======================================================================

def solve_slr(
    examples: List[Tuple[str, str]],
    top_k: int = 5,
) -> Dict[str, Any]:
    """
    Parameters
    ----------
    examples : list of (facts_string, direction_label)
    top_k    : number of top candidates to return

    Returns
    -------
    dict with "success", "program", "top_k_programs", "score"
    """

    pos_pairs = [(f, l) for f, l in examples if l == "eastbound"]
    neg_pairs = [(f, l) for f, l in examples if l == "westbound"]

    if not pos_pairs or not neg_pairs:
        return {
            "success": False,
            "program": "",
            "top_k_programs": [],
            "score": 0.0,
        }

    pos_facts = [parse_facts(f) for f, _ in pos_pairs]
    pos_cars = [extract_cars(pf) for pf in pos_facts]
    neg_facts = [parse_facts(f) for f, _ in neg_pairs]
    neg_cars = [extract_cars(nf) for nf in neg_facts]

    validation_program = build_validation_program(examples)

    # ---- Collect candidates (each entry: (rule_string, complexity)) ----
    candidates: List[Tuple[str, int]] = []

    # --- Stage 1: Single categorical property ---
    for pred, value in gen_single_props(pos_facts, pos_cars, neg_facts, neg_cars):
        rule = rule_for_single(pred, value)
        candidates.append((rule, rule_complexity(rule)))

    # --- Stage 1b: Integer property ---
    for pred, cond_val in gen_int_props(pos_facts, pos_cars, neg_facts, neg_cars):
        if ">" in cond_val:
            rule = rule_for_int(pred, cond_val)
        else:
            rule = rule_for_single(pred, cond_val)
        candidates.append((rule, rule_complexity(rule)))

    # --- Stage 1c: Negation rules (_X \\= excluded) ---
    for pred, excluded in gen_negation_rules(pos_facts, pos_cars, neg_facts, neg_cars):
        rule = rule_for_negation(pred, excluded)
        candidates.append((rule, rule_complexity(rule)))

    # --- Stage 1d: Universal negation (\\+ ...) ---
    for pred, val in gen_universal_negation(pos_facts, pos_cars, neg_facts, neg_cars):
        rule = rule_for_universal_neg(pred, val)
        candidates.append((rule, rule_complexity(rule)))

    # --- Stage 2: 2-property conjunctions ---
    for combo in gen_conjunctions(pos_facts, pos_cars, neg_facts, neg_cars, 2, 2):
        rule = rule_for_conjunction(combo)
        candidates.append((rule, rule_complexity(rule)))

    # --- Stage 3: 3-property conjunctions ---
    for combo in gen_conjunctions(pos_facts, pos_cars, neg_facts, neg_cars, 3, 3):
        rule = rule_for_conjunction(combo)
        candidates.append((rule, rule_complexity(rule)))

    # --- Stage 4: 4-property conjunctions ---
    for combo in gen_conjunctions(pos_facts, pos_cars, neg_facts, neg_cars, 4, 4):
        rule = rule_for_conjunction(combo)
        candidates.append((rule, rule_complexity(rule)))

    # --- Stage 5: 5-property conjunctions ---
    for combo in gen_conjunctions(pos_facts, pos_cars, neg_facts, neg_cars, 5, 5):
        rule = rule_for_conjunction(combo)
        candidates.append((rule, rule_complexity(rule)))

    # --- Stage 6: Mixed int+categorical conjunctions ---
    for rule, comp in gen_mixed_int_conjunctions(
        pos_facts, pos_cars, neg_facts, neg_cars
    ):
        candidates.append((rule, comp))

    # ---- Deduplicate ----
    seen_rules: set = set()
    unique: List[Tuple[str, int]] = []
    for rule, comp in candidates:
        if rule not in seen_rules:
            seen_rules.add(rule)
            unique.append((rule, comp))

    # ---- Score via verifier (LIMIT calls — only top K by complexity) ----
    unique.sort(key=lambda x: x[1])

    scored: List[Tuple[str, float, int]] = []
    verified = 0
    MAX_VERIFIER_CALLS = 5

    for rule, comp in unique:
        if verified >= MAX_VERIFIER_CALLS:
            break
        score = _evaluate_rule(rule, validation_program)
        scored.append((rule, score, comp))
        verified += 1

    # If none scored 1.0 yet, verify a few more (complexity-1 candidates first)
    if not any(s >= 1.0 for _, s, _ in scored) and verified < MAX_VERIFIER_CALLS:
        for rule, comp in unique:
            if verified >= MAX_VERIFIER_CALLS + 3:
                break
            if rule not in {r for r, _, _ in scored}:
                score = _evaluate_rule(rule, validation_program)
                scored.append((rule, score, comp))
                verified += 1

    # ---- Sort by score desc, complexity asc ----
    scored.sort(key=lambda x: (-x[1], x[2]))

    # ---- Best rule from in-Python candidates (without verifier) ----
    if not any(s >= 1.0 for _, s, _ in scored) and unique:
        scored.insert(0, (unique[0][0], 0.0, unique[0][1]))

    top_rules = scored[:top_k]
    top_programs = [r[0] for r in top_rules]
    best_score = top_rules[0][1] if top_rules else 0.0
    best_rule = top_rules[0][0] if top_rules else ""

    return {
        "success": best_score >= 1.0,
        "program": best_rule,
        "top_k_programs": top_programs,
        "score": best_score,
    }


# ======================================================================
# Main (for testing)
# ======================================================================

if __name__ == "__main__":
    with open("/workspace/DEMOS.json") as f:
        import json
        data = json.load(f)

    for i in range(min(5, len(data))):
        d = data[i]
        examples = list(zip(d["input_examples"], d["output_examples"]))
        result = solve_slr(examples)
        print(f"\n=== Demo {i} ({d['difficulty']}, {d['rule_complexity']}) ===")
        print(f"  Success: {result['success']}")
        print(f"  Score:   {result['score']}")
        print(f"  Program: {result['program'][:120]}")
        if result["top_k_programs"]:
            print(f"  Top-{len(result['top_k_programs'])}: {result['top_k_programs'][:3]}")

