    for car in cars:
        for p, a in facts:
            if p == pred and a[0] == car and a[1] == value:
                return True
    return False

def _all_match(facts_list, cars_list, pred, value):
    for facts, cars in zip(facts_list, cars_list):
        if not _any_car(facts, cars, pred, value):
            return False
    return True

def _none_match(facts_list, cars_list, pred, value):
    for facts, cars in zip(facts_list, cars_list):
        if _any_car(facts, cars, pred, value):
            return False
    return True

def _any_conj(facts, cars, combo):
    for car in cars:
        if all(any(p == pred and a[0] == car and a[1] == value for p, a in facts) for pred, value in combo):
            return True
    return False

def _all_conj(facts_list, cars_list, combo):
    for facts, cars in zip(facts_list, cars_list):
        if not _any_conj(facts, cars, combo):
            return False
    return True

def _none_conj(facts_list, cars_list, combo):
    for facts, cars in zip(facts_list, cars_list):
        if _any_conj(facts, cars, combo):
            return False
    return True

