            if _all_conj(FL, CL, list(combo)) and _none_conj(NF, NCL, list(combo)):
                parts = ["has_car(T, C)"] + [f"{p}(C, {v})" for p, v in combo]
                rule = "eastbound(T) :- " + ", ".join(parts) + "."
                out.append((rule, rule_complexity(rule)))
    return out


def _gen_mixed_int_conjunctions(FL, CL, NF, NCL):
    cv = defaultdict(set)
    for facts in FL:
        for p, a in facts:
            if is_value_pred(p) and len(a) == 2:
                cv[p].add(a[1])
    ip = set()
    for facts in FL:
        for p, a in facts:
            if is_int_pred(p) and len(a) == 2:
                ip.add(p)
    out = []
    checked = 0
    for cat_pred in sorted(cv.keys()):
        for cat_val in cv[cat_pred]:
            for int_pred in sorted(ip):
                checked += 1
                if checked > MAX_MIXED_INT:
                    break
                pos_ok = True
                for pf, pc in zip(FL, CL):
                    found = False
                    for car in pc:
                        cat_ok = any(p == cat_pred and a[0] == car and a[1] == cat_val for p, a in pf)
                        if not cat_ok: continue
                        int_ok = any(p == int_pred and a[0] == car and len(a) == 2 and
                                     a[1].isdigit() and int(a[1]) > 0 for p, a in pf)
                        if cat_ok and int_ok:
                            found = True; break
                    if not found: pos_ok = False; break
                if not pos_ok: continue
                neg_ok = True
                for nf, nc in zip(NF, NCL):
                    for car in nc:
                        cat_ok = any(p == cat_pred and a[0] == car and a[1] == cat_val for p, a in nf)
                        if not cat_ok: continue
                        int_ok = any(p == int_pred and a[0] == car and len(a) == 2 and
                                     a[1].isdigit() and int(a[1]) > 0 for p, a in nf)
                        if cat_ok and int_ok:
                            neg_ok = False; break
                    if not neg_ok: break
                if pos_ok and neg_ok:
                    rule = f"eastbound(T) :- has_car(T, C), {cat_pred}(C, {cat_val}), {int_pred}(C, N), N > 0."
                    out.append((rule, rule_complexity(rule)))
            if checked > MAX_MIXED_INT: break
    return out


# ======================================================================
# 5. Verifier wrapper
# ======================================================================

def _evaluate_rule(rule: str, validation_program: str) -> float:
    try:
        entry = {"validation program": validation_program}
        result = reward(rule, True, entry)
        return float(result.get("value", 0.0))
    except Exception:
        return 0.0


def build_validation_program(examples):
    lines = []
    seen = set()
    for facts_str, label in examples:
        facts = parse_facts(facts_str)
        tid = extract_train_id(facts)
        if not tid or tid in seen: continue
        seen.add(tid)
        lines.append(f"{label}({tid}).")
        for pred, args in facts:
            if pred == "has_car":
                lines.append(f"{pred}({args[0]}, {args[1]}).")
            else:
                lines.append(f"{pred}({', '.join(args)}).")
    return "\n".join(lines) + "\n"


# ======================================================================
# 6. Main solver — generates candidates stage-by-stage, verifies top-K
# ======================================================================

def solve_slr(examples, top_k=5):
    pos_pairs = [(f, l) for f, l in examples if l == "eastbound"]
    neg_pairs = [(f, l) for f, l in examples if l == "westbound"]
    if not pos_pairs or not neg_pairs:
        return {"success": False, "program": "", "top_k_programs": [], "score": 0.0}

    FL = [parse_facts(f) for f, _ in pos_pairs]
    CL = [extract_cars(pf) for pf in FL]
    NF = [parse_facts(f) for f, _ in neg_pairs]
    NCL = [extract_cars(nf) for nf in NF]
    vp = build_validation_program(examples)

    # ---- Stage-by-stage generation + verification ----
    all_scored: List[Tuple[str, float, int]] = []
    verified = 0
    MAX_VERIFIER = 3  # Only verify 3 simplest rules

    # Stage 1: Single categorical
    rules1 = _gen_single_props(FL, CL, NF, NCL)
    for rule, comp in rules1:
        all_scored.append((rule, 0.0, comp))

    # Stage 1b: Integer
    rules1b = _gen_int_props(FL, CL, NF, NCL)
    for rule, comp in rules1b:
        all_scored.append((rule, 0.0, comp))

    # Stage 1c: Negation
    rules1c = _gen_negation_rules(FL, CL, NF, NCL)
    for rule, comp in rules1c:
        all_scored.append((rule, 0.0, comp))

    # Stage 1d: Universal negation
    rules1d = _gen_universal_negation(FL, CL, NF, NCL)
    for rule, comp in rules1d:
        all_scored.append((rule, 0.0, comp))

    # Stage 2-5: Conjunctions (only if no single-property found)
    if not rules1 and not rules1b and not rules1c and not rules1d:
        for sz in range(2, 4):
            rules = _gen_conjunctions(FL, CL, NF, NCL, sz, sz)
            for rule, comp in rules:
                all_scored.append((rule, 0.0, comp))
        # Mixed int
        rules_mix = _gen_mixed_int_conjunctions(FL, CL, NF, NCL)
        for rule, comp in rules_mix:
            all_scored.append((rule, 0.0, comp))

    # Deduplicate
    seen_r = set()
    unique = []
    for rule, comp in all_scored:
        if rule not in seen_r:
            seen_r.add(rule)
            unique.append((rule, comp))

    # Sort by complexity
    unique.sort(key=lambda x: x[1])

    # Verify top candidates (by complexity, prefer earlier stages)
    scored = []
    for rule, comp in unique:
        if verified >= MAX_VERIFIER: break
        s = _evaluate_rule(rule, vp)
        scored.append((rule, s, comp))
        verified += 1

    # If no perfect score, verify a few more
    if not any(s >= 1.0 for _, s, _ in scored) and verified < MAX_VERIFIER:
        for rule, comp in unique:
            if verified >= MAX_VERIFIER + 2: break
            if rule not in {r for r, _, _ in scored}:
                s = _evaluate_rule(rule, vp)
                scored.append((rule, s, comp))
                verified += 1

    scored.sort(key=lambda x: (-x[1], x[2]))

    # Fallback to best in-Python candidate
    if not any(s >= 1.0 for _, s, _ in scored) and unique:
        scored.insert(0, (unique[0][0], 0.0, unique[0][1]))

    top = scored[:top_k]
    return {
        "success": top[0][1] >= 1.0 if top else False,
        "program": top[0][0] if top else "",
        "top_k_programs": [r[0] for r in top],
        "score": top[0][1] if top else 0.0,
    }


if __name__ == "__main__":
    with open("/workspace/DEMOS.json") as f:
        import json; data = json.load(f)
    for i in range(min(5, len(data))):
        d = data[i]
        ex = list(zip(d["input_examples"], d["output_examples"]))
        r = solve_slr(ex)
        print(f"Demo {i}: success={r['success']} score={r['score']} rule={r['program'][:80]}")
