neg_facts = [parse_facts(f) for f, _ in neg]
neg_cars = [[a[1] for p, a in f if p == "has_car"] for f in neg_facts]

_INT_PREDICATES = {"car_num", "has_wheel", "load_num", "passenger_num"}
_VALUE_PREDICATES = {"car_color", "car_len", "has_wall", "has_roof", "has_payload", "car_type", "has_window"}

# Try mixed int conjunctions
cv = defaultdict(set)
for facts in pos_facts:
    for p, a in facts:
        if p in _VALUE_PREDICATES and len(a) == 2:
            cv[p].add(a[1])

ip = set()
for facts in pos_facts:
    for p, a in facts:
        if p in _INT_PREDICATES and len(a) == 2:
            ip.add(p)

print(f"cat_vals: {cv}")
print(f"int_preds: {ip}")

for cat_pred in sorted(cv.keys()):
    for cat_val in cv[cat_pred]:
        for int_pred in sorted(ip):
            # Check positive
            pos_ok = True
            for pf, pc in zip(pos_facts, pos_cars):
                found = False
                for car in pc:
                    cat_ok = any(p == cat_pred and a[0] == car and a[1] == cat_val for p, a in pf)
                    if not cat_ok: continue
                    int_ok = any(p == int_pred and a[0] == car and len(a) == 2 and a[1].isdigit() and int(a[1]) > 0 for p, a in pf)
                    if cat_ok and int_ok:
                        found = True; break
                if not found:
                    pos_ok = False; break
            if not pos_ok: continue

            neg_ok = True
            for nf, nc in zip(neg_facts, neg_cars):
                for car in nc:
                    cat_ok = any(p == cat_pred and a[0] == car and a[1] == cat_val for p, a in nf)
                    if not cat_ok: continue
                    int_ok = any(p == int_pred and a[0] == car and len(a) == 2 and a[1].isdigit() and int(a[1]) > 0 for p, a in nf)
                    if cat_ok and int_ok:
                        neg_ok = False; break
                if not neg_ok: break

            if pos_ok and neg_ok:
                print(f"Found: {cat_pred}={cat_val}, {int_pred}>0")

