import json, re
from collections import defaultdict

with open('/workspace/DEMOS.json') as f:
    data = json.load(f)

d = data[8]
examples = list(zip(d['input_examples'], d['output_examples']))

pos = [(f, l) for f, l in examples if l == "eastbound"]
neg = [(f, l) for f, l in examples if l == "westbound"]

def parse_facts(s):
    return [(m.group(1), tuple(a.strip() for a in m.group(2).split(",")))
            for m in re.finditer(r"(\w+)\(([^)]*)\)", s)]

def get_car_props(facts_str):
    facts = parse_facts(facts_str)
    props = defaultdict(set)
    for p, a in facts:
        if p != "has_car" and len(a) == 2:
            props[a[0]].add((p, a[1]))
    return dict(props)

# Get ALL property values for each example
pos_vals = defaultdict(set)
neg_vals = defaultdict(set)
for facts_str, label in examples:
    props = get_car_props(facts_str)
    target = pos_vals if label == "eastbound" else neg_vals
    for car, preds in props.items():
        for p, a in preds:
            target[(p, a[0], a[1])].add(car)

# Check: what values exist in ALL negatives but NONE in positives?
print("Values in ALL negatives but NONE in positives:")
for (p, a0, a1) in sorted(neg_vals.keys()):
    if (p, a0, a1) not in pos_vals:
        print(f"  {p}({a0}, {a1})")

# What values exist in ALL positives?
print("\nValues in ALL positives:")
for (p, a0, a1) in sorted(pos_vals.keys()):
    all_pos_have = True
    for facts_str, label in examples:
        if label != "eastbound": continue
        props = get_car_props(facts_str)
        found = any(a[0] == a0 and a[1] == a1 for car, preds in props.items() for a in preds)
        if not found:
            all_pos_have = False
            break
    if all_pos_have:
        print(f"  {p}({a0}, {a1})")

