with open('/workspace/DEMOS.json') as f:
    data = json.load(f)

d = data[8]
examples = list(zip(d['input_examples'], d['output_examples']))

pos = [(f, l) for f, l in examples if l == "eastbound"]
neg = [(f, l) for f, l in examples if l == "westbound"]

def parse_facts(s):
    return [(m.group(1), tuple(a.strip() for a in m.group(2).split(",")))
            for m in re.finditer(r"(\w+)\(([^)]*)\)", s)]

pos_facts = [parse_facts(f) for f, _ in pos]
pos_cars = [[a[1] for p, a in f if p == "has_car"] for f in pos_facts]
neg_facts = [parse_facts(f) for f, _ in neg]
neg_cars = [[a[1] for p, a in f if p == "has_car"] for f in neg_facts]

# Simulate _gen_universal_negation
def _univ_any(facts, cars, pred, value):
    for car in cars:
        for p, a in facts:
            if p == pred and a[0] == car and a[1] == value:
                return True
    return False

def _univ_all(FL, CL, pred, value):
    return all(not _univ_any(f, c, pred, value) for f, c in zip(FL, CL))

def _univ_some(FL, CL, pred, value):
    return any(_univ_any(f, c, pred, value) for f, c in zip(FL, CL))

# Gather all candidates from positive examples
vals = defaultdict(set)
for facts in pos_facts:
    for p, a in facts:
        if len(a) == 2:
            vals[p].add(a[1])

print("Testing universal negation for demo 8:")
for pred in sorted(vals.keys()):
    for val in sorted(vals[pred]):
