import json, re
from collections import defaultdict

with open('/workspace/DEMOS.json') as f:
    data = json.load(f)

d = data[10]
examples = list(zip(d['input_examples'], d['output_examples']))

def parse_facts(s):
    return [(m.group(1), tuple(a.strip() for a in m.group(2).split(",")))
            for m in re.finditer(r"(\w+)\(([^)]*)\)", s)]

# For each example, collect ALL car properties
print("Demo 10 - ALL properties per train:")
for facts_str, label in examples:
    facts = parse_facts(facts_str)
    cars = {}
    for p, a in facts:
        if p == "has_car":
            cars[a[1]] = set()
    for p, a in facts:
        if p != "has_car" and len(a) == 2 and a[0] in cars:
            cars[a[0]].add((p, a[1]))

    print(f"\n  {label}:")
    for car in sorted(cars.keys()):
        print(f"    {car}: {sorted(cars[car])}")

